import { type RequestHandler } from '@builder.io/qwik-city';
import { startBackgroundRunner } from '../runner/runner';

export const onRequest: RequestHandler = async (event) => {
  // Start the background runner on any server-side request (if not already running)
  startBackgroundRunner();
  await event.next();
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { getAllTasks, createTask, getTaskById, Task } from '../../../db/db';

export const onGet: RequestHandler = async (event) => {
  try {
    const tasks = getAllTasks();
    event.json(200, tasks);
  } catch (err: any) {
    event.json(500, { error: err.message || 'Internal Server Error' });
  }
};

export const onPost: RequestHandler = async (event) => {
  try {
    let body: any;
    try {
      body = await event.request.json();
    } catch (e) {
      event.json(400, { error: 'Invalid JSON body' });
      return;
    }

    const { id, name, command, interval_seconds, status } = body;

    // Validation
    if (!id || typeof id !== 'string' || id.trim() === '') {
      event.json(400, { error: 'id is required and must be a non-empty string' });
      return;
    }
    if (!name || typeof name !== 'string' || name.trim() === '') {
      event.json(400, { error: 'name is required and must be a non-empty string' });
      return;
    }
    if (!command || typeof command !== 'string' || command.trim() === '') {
      event.json(400, { error: 'command is required and must be a non-empty string' });
      return;
    }
    if (
      interval_seconds === undefined ||
      typeof interval_seconds !== 'number' ||
      interval_seconds <= 0
    ) {
      event.json(400, { error: 'interval_seconds is required and must be a positive number' });
      return;
    }
    if (status !== 'ACTIVE' && status !== 'PAUSED') {
      event.json(400, { error: "status is required and must be either 'ACTIVE' or 'PAUSED'" });
      return;
    }

    // Check for duplicate ID
    const existing = getTaskById(id);
    if (existing) {
      event.json(400, { error: `Task with id '${id}' already exists` });
      return;
    }

    const newTask: Task = {
      id,
      name,
      command,
      interval_seconds,
      status,
    };

    createTask(newTask);

    event.json(201, newTask);
  } catch (err: any) {
    event.json(500, { error: err.message || 'Internal Server Error' });
  }
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { getTaskById, updateTaskStatus } from '../../../../db/db';

export const onPost: RequestHandler = async (event) => {
  try {
    const { id } = event.params;
    const task = getTaskById(id);

    if (!task) {
      event.json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    updateTaskStatus(id, 'PAUSED');

    event.json(200, {
      id,
      status: 'PAUSED',
    });
  } catch (err: any) {
    event.json(500, { error: err.message || 'Internal Server Error' });
  }
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { getTaskById, updateTaskStatus } from '../../../../db/db';

export const onPost: RequestHandler = async (event) => {
  try {
    const { id } = event.params;
    const task = getTaskById(id);

    if (!task) {
      event.json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    updateTaskStatus(id, 'ACTIVE');

    event.json(200, {
      id,
      status: 'ACTIVE',
    });
  } catch (err: any) {
    event.json(500, { error: err.message || 'Internal Server Error' });
  }
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { getTaskById } from '../../../../db/db';
import { executeTaskCommand } from '../../../../runner/runner';

export const onPost: RequestHandler = async (event) => {
  try {
    const { id } = event.params;
    const task = getTaskById(id);

    if (!task) {
      event.json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    // Trigger immediately in the background
    executeTaskCommand(task.id, task.command);

    event.json(200, {
      id,
      triggered: true,
    });
  } catch (err: any) {
    event.json(500, { error: err.message || 'Internal Server Error' });
  }
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { getTaskById, getExecutionHistory } from '../../../../db/db';

export const onGet: RequestHandler = async (event) => {
  try {
    const { id } = event.params;
    const task = getTaskById(id);

    if (!task) {
      event.json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    const history = getExecutionHistory(id);
    event.json(200, history);
  } catch (err: any) {
    event.json(500, { error: err.message || 'Internal Server Error' });
  }
};

import { component$, useStore, useVisibleTask$ } from '@builder.io/qwik';
import { routeLoader$ } from '@builder.io/qwik-city';
import { getAllTasks, getAllExecutionHistory, Task, ExecutionHistory } from '../../db/db';

export const useTasksData = routeLoader$(() => {
  const tasks = getAllTasks();
  const history = getAllExecutionHistory();
  return { tasks, history };
});

export default component$(() => {
  const initialData = useTasksData();

  const state = useStore({
    tasks: initialData.value.tasks as Task[],
    history: initialData.value.history as ExecutionHistory[],
    errorMsg: '',
    successMsg: '',
    form: {
      id: '',
      name: '',
      command: '',
      interval_seconds: 5,
      status: 'ACTIVE' as 'ACTIVE' | 'PAUSED',
    },
    isSubmitting: false,
  });

  // Client-side polling to keep tasks and history updated in real-time
  useVisibleTask$(() => {
    const interval = setInterval(async () => {
      try {
        // Fetch tasks
        const tasksRes = await fetch('/api/tasks');
        if (tasksRes.ok) {
          const tasks = (await tasksRes.json()) as Task[];
          state.tasks = tasks;

          // Fetch history for each task and merge
          const allHistory: ExecutionHistory[] = [];
          for (const task of tasks) {
            const histRes = await fetch(`/api/tasks/${task.id}/history`);
            if (histRes.ok) {
              const hist = (await histRes.json()) as ExecutionHistory[];
              allHistory.push(...hist);
            }
          }

          // Sort by timestamp descending
          allHistory.sort(
            (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
          );

          state.history = allHistory;
        }
      } catch (err) {
        console.error('Error polling tasks/history:', err);
      }
    }, 2000);

    return () => clearInterval(interval);
  });

  const clearMessages = () => {
    state.errorMsg = '';
    state.successMsg = '';
  };

  const handleCreateTask = async () => {
    clearMessages();
    state.isSubmitting = true;

    try {
      const response = await fetch('/api/tasks', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          id: state.form.id,
          name: state.form.name,
          command: state.form.command,
          interval_seconds: Number(state.form.interval_seconds),
          status: state.form.status,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        state.errorMsg = data.error || 'Failed to create task';
      } else {
        state.successMsg = `Task '${data.name}' created successfully!`;
        // Reset form
        state.form = {
          id: '',
          name: '',
          command: '',
          interval_seconds: 5,
          status: 'ACTIVE',
        };

        // Immediately update state
        const tasksRes = await fetch('/api/tasks');
        if (tasksRes.ok) {
          state.tasks = await tasksRes.json();
        }
      }
    } catch (err: any) {
      state.errorMsg = err.message || 'An unexpected error occurred';
    } finally {
      state.isSubmitting = false;
    }
  };

  const handlePause = async (id: string) => {
    clearMessages();
    try {
      const res = await fetch(`/api/tasks/${id}/pause`, { method: 'POST' });
      const data = await res.json();
      if (!res.ok) {
        state.errorMsg = data.error || 'Failed to pause task';
      } else {
        state.successMsg = `Task '${id}' paused.`;
        // Update local task status
        const idx = state.tasks.findIndex((t) => t.id === id);
        if (idx !== -1) {
          state.tasks[idx].status = 'PAUSED';
        }
      }
    } catch (err: any) {
      state.errorMsg = err.message || 'An unexpected error occurred';
    }
  };

  const handleResume = async (id: string) => {
    clearMessages();
    try {
      const res = await fetch(`/api/tasks/${id}/resume`, { method: 'POST' });
      const data = await res.json();
      if (!res.ok) {
        state.errorMsg = data.error || 'Failed to resume task';
      } else {
        state.successMsg = `Task '${id}' resumed.`;
        // Update local task status
        const idx = state.tasks.findIndex((t) => t.id === id);
        if (idx !== -1) {
          state.tasks[idx].status = 'ACTIVE';
        }
      }
    } catch (err: any) {
      state.errorMsg = err.message || 'An unexpected error occurred';
    }
  };

  const handleTrigger = async (id: string) => {
    clearMessages();
    try {
      const res = await fetch(`/api/tasks/${id}/trigger`, { method: 'POST' });
      const data = await res.json();
      if (!res.ok) {
        state.errorMsg = data.error || 'Failed to trigger task';
      } else {
        state.successMsg = `Task '${id}' triggered in the background.`;
      }
    } catch (err: any) {
      state.errorMsg = err.message || 'An unexpected error occurred';
    }
  };

  return (
    <div class="dashboard-container">
      {/* CSS Styles */}
      <style>{`
        .dashboard-container {
          max-width: 1200px;
          margin: 0 auto;
          padding: 2rem 1.5rem;
          font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
          color: #1f2937;
          background-color: #f9fafb;
          min-height: 100vh;
        }

        h1 {
          font-size: 2.25rem;
          font-weight: 800;
          color: #111827;
          margin-bottom: 0.5rem;
        }

        .subtitle {
          color: #4b5563;
          margin-bottom: 2rem;
          font-size: 1.1rem;
        }

        .alert {
          padding: 1rem;
          border-radius: 0.5rem;
          margin-bottom: 1.5rem;
          font-weight: 500;
        }

        .alert-success {
          background-color: #d1fae5;
          color: #065f46;
          border: 1px solid #a7f3d0;
        }

        .alert-error {
          background-color: #fee2e2;
          color: #991b1b;
          border: 1px solid #fca5a5;
        }

        .grid-layout {
          display: grid;
          grid-template-columns: 1fr;
          gap: 2rem;
          margin-bottom: 2.5rem;
        }

        @media (min-width: 768px) {
          .grid-layout {
            grid-template-columns: 1fr 2fr;
          }
        }

        .card {
          background: #ffffff;
          border-radius: 0.75rem;
          box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
          padding: 1.5rem;
          border: 1px solid #e5e7eb;
        }

        .card-title {
          font-size: 1.25rem;
          font-weight: 700;
          color: #111827;
          margin-bottom: 1.25rem;
          border-bottom: 2px solid #f3f4f6;
          padding-bottom: 0.5rem;
        }

        /* Form styling */
        .form-group {
          margin-bottom: 1rem;
        }

        .form-group label {
          display: block;
          font-size: 0.875rem;
          font-weight: 600;
          color: #374151;
          margin-bottom: 0.375rem;
        }

        .form-control {
          width: 100%;
          padding: 0.625rem 0.75rem;
          font-size: 0.875rem;
          border: 1px solid #d1d5db;
